import { createServer } from "node:http";
import postgres from "postgres";
import { createChatActionHandler } from "@springroll/chat-actions";
import { createPostgresActionStore, POSTGRES_ACTION_SCHEMA, type ActionSqlClient } from "@springroll/chat-actions/postgres";
import { nodeChatActionListener } from "@springroll/chat-actions/node";
import { authorizeOwnTask, exampleTaskManifest } from "@springroll/chat-actions/example";

const database = postgres(process.env.DATABASE_URL!);
// Disposable acceptance app. Production apps install the schema through their migrations.
await database.unsafe(POSTGRES_ACTION_SCHEMA);
const client = (sql: postgres.Sql | postgres.TransactionSql): ActionSqlClient => ({ async query<T extends Record<string, unknown>>(statement: string, values: readonly unknown[]) {
  return { rows: await sql.unsafe<T[]>(statement, values as postgres.ParameterOrJSON<never>[]) };
} });
const store = createPostgresActionStore({ ...client(database), transaction: async run => {
  let result: unknown;
  await database.begin(async transaction => { result = await run(client(transaction)); });
  return result as never;
} });
const handler = createChatActionHandler({
  controlPlaneUrl: new URL(process.env.SPRINGROLL_DATA_URL!).origin,
  applicationToken: process.env.SPRINGROLL_DATA_TOKEN!, manifest: exampleTaskManifest, store,
  authorize: authorizeOwnTask,
  createRecord: ({ principal, data }) => ({ ...data, owner_membership_id: principal.membershipId }),
});
const actions = nodeChatActionListener(handler);
createServer((request, response) => {
  if (request.url === "/healthz") { response.writeHead(200, { "Content-Type": "application/json" }); response.end(JSON.stringify({ ok: true, workload: "chat-node-postgres" })); return; }
  void actions(request, response);
}).listen(Number(process.env.PORT ?? 8080), "0.0.0.0");
